def getServerId(num_servers, requests):
    size = 1
    while size < num_servers:
        size *= 2
    INF = (float('inf'), float('inf'))
    tree = [INF] * (2 * size)
    for i in range(num_servers):
        tree[size + i] = (0, i)
    for i in range(size - 1, 0, -1):
        tree[i] = min(tree[2 * i], tree[2 * i + 1])

    def query(r):  # min over [0, r)
        best, lo, hi = INF, size, size + r
        while lo < hi:
            if lo & 1:
                best = min(best, tree[lo]); lo += 1
            if hi & 1:
                hi -= 1; best = min(best, tree[hi])
            lo //= 2; hi //= 2
        return best

    res = []
    for r in requests:
        load, sid = query(min(max(r, 1), num_servers))
        i = size + sid
        tree[i] = (load + 1, sid)
        i //= 2
        while i:
            tree[i] = min(tree[2 * i], tree[2 * i + 1]); i //= 2
        res.append(sid)
    return res

class Solution {
    public int[] getServerId(int num_servers, int[] requests) {
        int[] load = new int[num_servers];
        int[] res = new int[requests.length];
        for (int q = 0; q < requests.length; q++) {
            int upper = Math.min(Math.max(requests[q], 1), num_servers);
            int bestId = 0, bestLoad = load[0];
            for (int i = 1; i < upper; i++) if (load[i] < bestLoad) { bestLoad = load[i]; bestId = i; }
            load[bestId]++;
            res[q] = bestId;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> getServerId(int num_servers, vector<int>& requests) {
        vector<int> load(num_servers, 0), res;
        for (int r : requests) {
            int upper = min(max(r, 1), num_servers);
            int bestId = 0, bestLoad = load[0];
            for (int i = 1; i < upper; i++) if (load[i] < bestLoad) { bestLoad = load[i]; bestId = i; }
            load[bestId]++;
            res.push_back(bestId);
        }
        return res;
    }
};
